mapper.sql:
f.review_status = 'APPROVED'

    AND (
        INSTR(LOWER(f.name), LOWER(#{keyword})) > 0
        OR INSTR(LOWER(COALESCE(f.ingredients, '')), LOWER(#{keyword})) > 0
        OR INSTR(LOWER(COALESCE(f.city, '')), LOWER(#{keyword})) > 0
        OR INSTR(LOWER(COALESCE(f.province, '')), LOWER(#{keyword})) > 0
    )


    AND f.region_id = #{regionId}



    AND f.latitude BETWEEN #{minLatitude} AND #{maxLatitude}


            AND f.longitude BETWEEN #{minLongitude} AND #{maxLongitude}


            AND (f.longitude >= #{minLongitude} OR f.longitude <= #{maxLongitude})


AND LEAST(POWER(2, #{zoom})-1,FLOOR((f.longitude + 180) / 360 * POWER(2, #{zoom})))=#{clusterX}
AND FLOOR((1 - LN(TAN(RADIANS(LEAST(85, GREATEST(-85, f.latitude)))) +
    1 / COS(RADIANS(LEAST(85, GREATEST(-85, f.latitude))))) / PI()) / 2 * POWER(2, #{zoom}))=#{clusterY}

mapper.select:
SELECT 
FROM food f
LEFT JOIN region r ON r.id = f.region_id

    WHERE f.review_status = #{status}

ORDER BY FIELD(f.review_status, 'PENDING', 'APPROVED', 'REJECTED'), f.id DESC
LIMIT #{pageSize} OFFSET #{offset}

SELECT f.id AS food_id,f.name AS food_name,f.latitude,f.longitude,f.image_url,f.heat,f.review_status, f.created_by,f.created_by_user_id,f.created_at,f.ingredients,LEFT(f.summary,240) AS summary, r.id AS region_id,COALESCE(NULLIF(f.city,''),r.name) AS region_name, COALESCE(NULLIF(f.province,''),r.province) AS region_province FROM food f LEFT JOIN region r ON r.id = f.region_id WHERE f.review_status = 'APPROVED'
AND INSTR(LOWER(f.name), LOWER(#{token})) > 0 OR INSTR(LOWER(COALESCE(f.ingredients, '')), LOWER(#{token})) > 0 OR INSTR(LOWER(COALESCE(f.city, '')), LOWER(#{token})) > 0 OR INSTR(LOWER(COALESCE(f.province, '')), LOWER(#{token})) > 0
AND 1=0 ORDER BY f.heat DESC, f.id DESC LIMIT #{limit}

SELECT COUNT(*)
FROM food

    WHERE review_status = #{status}

SELECT COUNT(*)
FROM food
WHERE image_url = #{imageUrl}

